def process(ej_populations) -> pd.DataFrame:
    high_ej = ej_populations[ej_populations['Percent of population in EJ BGs'] > 50]['Municipality'].tolist()
    low_ej = ej_populations[ej_populations['Percent of population in EJ BGs'] < 25]['Municipality'].tolist()

    df = pd.DataFrame({
        'Municipality': high_ej + low_ej,
        'EJ_Category': ['High (>50%)'] * len(high_ej) + ['Low (<25%)'] * len(low_ej)
    })
    return df

def process(marine_samples_2023, ej_high_low_communities) -> pd.DataFrame:
    return marine_samples_2023.merge(
        ej_high_low_communities,
        left_on='Community',
        right_on='Municipality',
        how='inner'
    )

def process(marine_with_ej) -> pd.DataFrame:
    results = []
    for ej_cat in ['High (>50%)', 'Low (<25%)']:
        subset = marine_with_ej[marine_with_ej['EJ_Category'] == ej_cat]
        total_samples = len(subset)
        violations = (subset['Violation'] == 'Yes').sum()
        exceedance_rate = (violations / total_samples * 100) if total_samples > 0 else 0
        results.append({
            'EJ_Category': ej_cat,
            'Total_Samples': total_samples,
            'Violations': violations,
            'Exceedance_Rate': exceedance_rate
        })
    return pd.DataFrame(results)

def process(bacterial_exceedance_rates) -> pd.DataFrame:
    high_ej = bacterial_exceedance_rates[bacterial_exceedance_rates['EJ_Category'] == 'High (>50%)']['Exceedance_Rate'].values[0]
    low_ej = bacterial_exceedance_rates[bacterial_exceedance_rates['EJ_Category'] == 'Low (<25%)']['Exceedance_Rate'].values[0]
    difference = round(high_ej - low_ej, 2)
    return pd.DataFrame({'Difference': [difference]})
